-- 5. Patrols (Pandaria 5.4.8, same guids)
DELETE FROM `waypoint_data` WHERE `id` BETWEEN 429002001 AND 429003000;
ON DUPLICATE KEY UPDATE `path_id`=VALUES(`path_id`);
UPDATE `creature` SET `MovementType`=2, `spawndist`=0 WHERE `guid` IN (323249, 323428, 323429, 323430, 323793, 323795);

-- Random wandering (AzerothCore wander radius)
