-- Check
SELECT CONCAT('Mastiff ', (SELECT `unit_flags` FROM `creature_template` WHERE `entry` = 13036),
              ', Slip''kik ', (SELECT `unit_flags` FROM `creature_template` WHERE `entry` = 14323),
              ', Spirit ', (SELECT `unit_flags` FROM `creature_template` WHERE `entry` = 11446),
              ', ', (SELECT COUNT(*) FROM `gameobject` WHERE `map` = 429 AND `id` IN (179526, 179528, 179532, 179533)), ' Warpwood Pods') AS `dire_maul_north`;
